import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Sun, Moon, Home, Info, Settings, User, LogOut, Globe } from 'lucide-react';

const Header = ({ darkMode, toggleDarkMode, isAuthenticated, onLogout }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langOpen, setLangOpen] = useState(false);
  const [lang, setLang] = useState("fr");
  const navigate = useNavigate();

  // Traductions
  const translations = {
    fr: {
      home: "Accueil",
      about: "À propos",
      dashboard: "Tableau de bord",
      profile: "Profil",
      settings: "Paramètres",
      login: "Connexion",
      register: "Créer un compte",
      logout: "Déconnexion"
    },
    en: {
      home: "Home",
      about: "About",
      dashboard: "Dashboard",
      profile: "Profile",
      settings: "Settings",
      login: "Login",
      register: "Register",
      logout: "Logout"
    },
    mg: {
      home: "Fandraisana",
      about: "Mombamomba",
      dashboard: "Dashboard",
      profile: "Tantara",
      settings: "Fikirana",
      login: "Hiditra",
      register: "Hisoratra",
      logout: "Hivoaka"
    }
  };

  const t = translations[lang];

  // Menu navigation basé sur l'authentification
  const getNavItems = () => {
    const baseItems = [
      { icon: <Home size={20} />, label: t.home, path: "/" },
      { icon: <Info size={20} />, label: t.about, path: "/about" },
    ];

    if (isAuthenticated) {
      return [
        ...baseItems,
        { icon: <Home size={20} />, label: t.dashboard, path: "/dashboard" },
        { icon: <User size={20} />, label: t.profile, path: "/profile" },
        { icon: <Settings size={20} />, label: t.settings, path: "/settings" },
      ];
    }

    return baseItems;
  };

  const navItems = getNavItems();

  const handleLogout = () => {
    onLogout();
    navigate('/login');
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-md">

      <div className="container mx-auto px-4 py-3 flex items-center justify-between">

        {/* LOGO */}
        <div className="flex items-center space-x-2 cursor-pointer" onClick={() => navigate('/')}>
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
            <span className="text-white font-bold">R</span>
          </div>
          <h1 className="text-xl font-bold dark:text-white">ReactUI</h1>
        </div>

        {/* NAV Desktop */}
        <nav className="hidden md:flex items-center space-x-4">
          {navItems.map((item) => (
            <Link
              key={item.label}
              to={item.path}
              className="flex items-center gap-2 px-3 py-2 rounded-lg
                         text-neutral-700 dark:text-neutral-300
                         hover:bg-neutral-100 dark:hover:bg-neutral-800 transition"
            >
              {item.icon}
              <span>{item.label}</span>
            </Link>
          ))}
        </nav>

        {/* ACTIONS */}
        <div className="flex items-center space-x-3">

          {/* LANG BUTTON */}
          <div className="relative">
            <button
              onClick={() => setLangOpen(!langOpen)}
              className="p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
            >
              <Globe size={20} />
            </button>

            {langOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white dark:bg-neutral-800 border dark:border-neutral-700 rounded-lg shadow-lg p-2 z-50">
                <button
                  onClick={() => { setLang("fr"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇫🇷 Français</button>

                <button
                  onClick={() => { setLang("en"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇬🇧 English</button>

                <button
                  onClick={() => { setLang("mg"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇲🇬 Malagasy</button>
              </div>
            )}
          </div>

          {/* Boutons Auth */}
          {!isAuthenticated ? (
            <>
              <Link to="/login" className="hidden md:flex items-center gap-2 px-4 py-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition">
                <span className="text-sm font-medium">{t.login}</span>
              </Link>

              <Link to="/register" className="hidden md:flex items-center gap-2 px-4 py-2 rounded-lg bg-primary-600 text-white hover:bg-primary-700 transition">
                <span className="text-sm font-medium">{t.register}</span>
              </Link>
            </>
          ) : (
            <button
              onClick={handleLogout}
              className="hidden md:flex items-center gap-2 px-4 py-2 rounded-lg bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-800/50 transition"
            >
              <LogOut size={18} />
              <span className="text-sm font-medium">{t.logout}</span>
            </button>
          )}

          {/* DARK MODE */}
          <button
            onClick={toggleDarkMode}
            className="p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          {/* MOBILE TOGGLE */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            <div className="space-y-1">
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "rotate-45 translate-y-2" : ""}`} />
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "opacity-0" : "opacity-100"}`} />
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "-rotate-45 -translate-y-2" : ""}`} />
            </div>
          </button>

        </div>
      </div>

      {/* MOBILE MENU */}
      {mobileMenuOpen && (
        <div className="md:hidden px-4 py-3 border-t dark:border-neutral-800 space-y-2 bg-white dark:bg-neutral-900">
          {navItems.map((item) => (
            <Link 
              key={item.label} 
              to={item.path}
              onClick={() => setMobileMenuOpen(false)}
              className="flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition"
            >
              {item.icon}
              <span>{item.label}</span>
            </Link>
          ))}

          {!isAuthenticated ? (
            <>
              <Link 
                to="/login" 
                onClick={() => setMobileMenuOpen(false)}
                className="flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 transition"
              >
                <span>{t.login}</span>
              </Link>

              <Link 
                to="/register" 
                onClick={() => setMobileMenuOpen(false)}
                className="flex items-center gap-3 px-4 py-3 rounded-lg bg-primary-600 text-white transition"
              >
                <span>{t.register}</span>
              </Link>
            </>
          ) : (
            <button
              onClick={() => {
                handleLogout();
                setMobileMenuOpen(false);
              }}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-lg bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-800/50 transition"
            >
              <LogOut size={18} />
              <span>{t.logout}</span>
            </button>
          )}
        </div>
      )}

    </header>
  );
};

export default Header;
